(function(){
'use strict';
const M=window.WA_MODEL,E=M.escape,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='ppo-warranty-customer-resolution-r01',icons=JSON.parse($('#icons').textContent);
const views=[['register','Warranty register'],['evidence','Failure & evidence'],['coverage','Coverage assessment'],['resolution','Resolution plan'],['customer','Customer outcome'],['supplier','Supplier recovery']];
let state=M.seed(),lastSaved=null,storageError='',pending=null,role='service',readState='live',fault='none';
let selected='wa-1',view='register',query='',filter='all',sort='due',ownerFilter='all';
let modalAction=null,modalVersion=0,modalDirty=false,opener=null,focusKey=null,toastTimer;
  const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
  const button=(act,label,extra='',cls='')=>`<button type="button" data-action="${act}" ${extra} class="${cls}">${label}</button>`;
  const pill=(label,kind='')=>`<span class="pill ${kind}">${E(label)}</span>`;
  const tone=s=>({Active:'success',Covered:'success',Reviewed:'success',Completed:'success',Deferred:'warning',Partial:'warning',Unknown:'warning',Draft:'info',Due:'info',Disputed:'danger',Expired:'danger',Cancelled:'danger',Skipped:'neutral',NotCovered:'warning',NotApplicable:'neutral'})[s]||'';
  const note=(body,type='neutral')=>`<div class="note ${type}">${body}</div>`;
  const date=s=>s?new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s.length===10?s+'T00:00:00Z':s)):'Not established';
  const pretty=s=>({FinanceReview:'Finance review',ContractReference:'Exact agreement reference',NotCovered:'Not covered',NotApplicable:'Not applicable'})[s]||s;
  const heading=(title,sub,actions='')=>`<div class="page-heading"><div><h2>${title}</h2><p>${sub}</p></div><div class="row">${actions}</div></div>`;
  const card=(title,body,extra='',foot='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${extra}</div><div class="pad">${body}</div>${foot?`<div class="card-foot">${foot}</div>`:''}</section>`;
  const empty=(title,body,action='')=>`<div class="empty"><h2>${title}</h2><p>${body}</p>${action}</div>`;
  const facts=rows=>`<dl class="facts">${rows.map(([k,v])=>`<dt>${E(k)}</dt><dd>${E(v)}</dd>`).join('')}</dl>`;
  const field=(name,label,value='',type='text',required=true)=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${required?'required':''} maxlength="2000"></div>`;
  const area=(name,label,value='',required=true)=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="2000" ${required?'required':''}>${E(value)}</textarea></div>`;
  const select=(name,label,options,value='',required=true)=>`<div class="field"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${E(v)}" ${v===value?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
  const check=(name,label)=>`<label class="check-label"><input type="checkbox" name="${name}" required>${label}</label>`;
  const ownerOptions=[['','Choose an owner'],...M.owners.map(x=>[x,x])];
const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(n/100);
const permitted=()=>role==='denied'||readState==='denied'?[]:state.cases.slice(0,readState==='partial'?2:30);
const now=()=>permitted().find(c=>c.id===selected);
const enabled=action=>M.can(role,action);
const actionButton=(action,label,primary=false,extra='')=>enabled(action)?button(action,label,extra,primary?'primary':''):'';
function attention(c){const k=M.claim(c);if(c.asset.identity!=='Verified')return 'Resolve equipment identity';if(M.customerState(c)==='Resolved'&&M.outstanding(k)>0)return 'Follow up the supplier claim';if(k&&M.response(k)?.status==='Rejected')return 'Review supplier rejection';if(!M.review(c))return 'Review the current evidence';if(!M.assessment(c))return 'Assess coverage and cause';if(!M.plan(c))return 'Prepare the customer remedy';if(!M.authorisation(c)&&!c.execution)return 'Review exact work authority';if(!c.execution)return 'Prepare and review service work';if(!c.updates.length)return 'Prepare a customer update';if(M.customerState(c)!=='Resolved')return 'Review the customer outcome';return 'Review remaining obligations';}
function selectedClaimStatus(c){const k=M.claim(c);return !k?'Not prepared':M.outstanding(k)===0?'Recovery disposed':M.response(k)?.status||(k.submission?'Submitted':'Prepared locally');}
const isReview=c=>!M.assessment(c)||['Unknown','Disputed'].includes(M.assessment(c).status);
function decisions(c){const a=M.assessment(c),p=M.plan(c),k=M.claim(c),g=M.goodwill(c,p);return `<div class="decision-grid">${[['Warranty',a?.status||'Unknown'],['Goodwill',g?.decision||'Not decided'],['Work authority',M.authorisation(c)?'Authorised scope':c.execution?'Retained with result':'Not authorised'],['Supplier',selectedClaimStatus(c)],['Finance credit',M.credited(k)>0?money(M.credited(k)):'None linked']].map(([label,value])=>`<div class="decision-cell">${label}<strong>${E(pretty(value))}</strong></div>`).join('')}</div>`;}
function timeline(c){return `<ol class="timeline">${c.history.slice().reverse().map(h=>`<li>${E(h.text)}${h.reason?`<p class="small">${E(h.reason)}</p>`:''}<small>${E(h.actor)} · ${date(h.at)}</small></li>`).join('')}</ol>`;}
const boundary=()=>note('Warranty, goodwill, work authority, supplier approval and Finance credit each retain their own decision and evidence.','neutral');
function followups(c){return c.followups.length?c.followups.map(f=>`<div class="decision-history"><div class="row between"><h3>${E(f.title)}</h3>${pill(f.state,f.state==='Completed'?'success':'warning')}</div><p class="small">${E(f.kind)} · ${E(f.owner)} · ${date(f.due)}</p>${f.outcome?`<p class="small">${E(f.outcome)}</p>`:enabled('completeFollowup')?`<div class="record-actions">${button('completeFollowup','Record outcome',`data-id="${E(f.id)}"`)}</div>`:''}</div>`).join(''):'<p class="small">No separate follow-up has been added. Case review, maintenance and claim ownership remain visible in their own records.</p>';}
function recordHistory(items,renderItem){return items.length?items.slice().reverse().map(x=>`<article class="decision-history">${renderItem(x)}</article>`).join(''):'<p class="small">No decision recorded yet.</p>';}
function renderRegister(){
 const all=permitted();let rows=all.filter(c=>(`${c.ref} ${c.title} ${c.customer} ${c.asset.name} ${c.asset.serial||''} ${c.owner} ${attention(c)}`.toLowerCase().includes(query.toLowerCase()))&&(ownerFilter==='all'||c.owner===ownerFilter)&&(filter==='all'||filter==='review'&&isReview(c)||filter==='customer'&&M.customerState(c)==='Resolved'||filter==='recovery'&&M.outstanding(M.claim(c))>0||filter==='identity'&&c.asset.identity!=='Verified'));
 rows.sort((a,b)=>sort==='name'?a.customer.localeCompare(b.customer):sort==='case'?a.ref.localeCompare(b.ref):a.due.localeCompare(b.due));
 return heading('Warranty register','Keep the customer remedy, technical decisions and outstanding recovery in view.')+`<div class="snapshot" aria-label="Warranty snapshot">${[['all','Cases',all.length,'Current permitted preview'],['review','Coverage to review',all.filter(isReview).length,'Unknown or disputed'],['customer','Customer resolved',all.filter(c=>M.customerState(c)==='Resolved').length,'Recovery may remain open'],['recovery','Recovery outstanding',all.filter(c=>M.outstanding(M.claim(c))>0).length,'Separate supplier / Finance action']].map(([id,label,count,sub])=>`<button type="button" data-filter="${id}" aria-pressed="${filter===id}"><span>${label}</span><strong>${count}</strong><small>${sub}</small></button>`).join('')}</div><section class="card"><div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="Search warranty cases" placeholder="Search customer, equipment, case or owner" value="${E(query)}"></label><select id="register-filter" aria-label="Case filter">${[['all','All cases'],['review','Coverage to review'],['customer','Customer resolved'],['recovery','Recovery outstanding'],['identity','Identity unresolved']].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select><select id="owner-filter" aria-label="Case owner">${[['all','All owners'],...M.owners.map(x=>[x,x])].map(([v,l])=>`<option value="${v}" ${v===ownerFilter?'selected':''}>${E(l)}</option>`).join('')}</select><select id="register-sort" aria-label="Case order">${[['due','Next review date'],['name','Customer name'],['case','Case reference']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="result-count">${rows.length} of ${all.length} cases · ${readState==='partial'?'Partial':'Complete fictional'} register · scenario as at ${date(M.TODAY)}</div>${rows.length?`<table class="queue-table"><thead><tr><th>Case / equipment</th><th>Coverage / customer</th><th>Recovery</th><th>Owner / next review</th><th>Next action</th><th><span class="tiny">Open</span></th></tr></thead><tbody>${rows.map(c=>`<tr class="${c.id===selected?'selected-row':''}"><td><span class="record-title">${E(c.title)}</span><span class="record-ref">${E(c.ref)} · ${E(c.asset.name)}</span><span class="record-ref">${E(c.customer)}</span></td><td data-label="Coverage / customer">${pill(pretty(M.assessment(c)?.status||'Unknown'),tone(M.assessment(c)?.status||'Unknown'))}<span class="record-ref">Customer: ${E(M.customerState(c))}</span></td><td data-label="Supplier recovery">${pill(selectedClaimStatus(c),M.outstanding(M.claim(c))>0?'warning':'')}<span class="record-ref">${M.claim(c)?money(M.outstanding(M.claim(c)))+' unresolved':'No claim prepared'}</span></td><td data-label="Owner / next review"><span>${E(c.owner)}</span><span class="record-ref">${date(c.due)}</span></td><td data-label="Next action"><span class="attention">${E(attention(c))}</span></td><td>${button('open','Open case',`data-case="${c.id}"`,'quiet')}</td></tr>`).join('')}</tbody></table>`:empty('No matching cases','Change your search or filters to find a permitted case.',button('clear','Clear filters'))}</section><div class="guide-strip"><div>${icon('help')}<span><b>Start with Willowbank.</b> Review uncertain coverage, authorise a replacement and resolve the customer outcome while supplier recovery remains open.</span></div>${button('guide','View demonstration','','quiet')}</div>`;
}
function renderEvidence(c){const r=M.review(c);return heading('Failure & evidence','Review what was observed, which equipment is involved and the exact evidence available.',actionButton('addEvidence','Add evidence reference')+actionButton('reviewEvidence','Review evidence',true))+decisions(c)+`<div class="two-col"><div class="stack">${card('Reported failure',`<p>${E(c.symptom)}</p><div class="detail-copy">${facts([['Reported',date(c.reported)],['Equipment',c.asset.name],['Serial',c.asset.serial||'Not established'],['Identity',c.asset.identity],['Located in',c.asset.location],['Serves',c.asset.serves.join(' · ')]])}</div>`,'','Observed symptoms do not establish causation. Any intervention needs its own authorised scope.')}<section class="card"><div class="card-head"><h2>Evidence register</h2>${pill('Set r'+c.evidenceRevision,r?'success':'warning')}</div>${c.evidence.map(e=>`<article class="source-row">${icon(e.illustration?'eye':'file')}<div><h3>${E(e.title)}</h3><p class="small">${E(e.ref)} · ${E(e.kind)} · ${date(e.date)}</p><div class="row">${pill(e.available?'Available':'Original unavailable',e.available?'':'warning')}${pill('Internal')}${e.supersedes?pill('Successor reference','info'):''}</div></div><div class="record-actions">${button('evidenceDetail','Inspect',`data-id="${e.id}"`,'quiet')}</div></article>`).join('')}</section>${c.id==='wa-1'&&c.sources.length===1?note(`<p>The original warranty commencement record is missing. The demonstration includes a recovered successor.</p><div class="record-actions">${actionButton('loadEvidence','Load missing demonstration evidence')}</div>`,'warning'):''}</div><aside class="stack">${card('Evidence review',r?facts([['Reviewed set','r'+r.evidenceRevision],['Terms revision','r'+r.sourceRevision],['Reviewer',r.actor],['Review basis',r.reason]]):'<p class="small">The current evidence set has not been reviewed. A new source or reference requires a new review.</p>',pill(r?'Reviewed':'Review needed',r?'success':'warning'))}${card('Related service context',`<p class="small">Continue from the original maintenance finding and retained service evidence. Opening a design does not transfer these local records.</p><div class="record-actions">${button('links','Linked workspaces')}${actionButton('assign','Assign next review')}</div>`)}${card('Case timeline',timeline(c))}</aside></div>`;}
function renderCoverage(c){const v=M.source(c),a=M.assessment(c),g=M.goodwill(c);return heading('Coverage assessment','Keep source terms, dates and causation explicit; record the owner of unresolved questions.',actionButton('assess','Record assessment',true))+decisions(c)+`<div class="two-col"><div class="stack">${card('Exact warranty terms',`<div class="row">${pill(v.ref)}${pill(v.available?'Source available':'Source unavailable',v.available?'':'danger')}</div><p class="detail-copy">${E(v.terms)}</p><p class="small detail-copy">${E(v.startBasis)}</p><div class="record-actions">${button('terms','Inspect retained terms','','link-button')}</div>`)}${card('Current assessment',a?`${pill(pretty(a.status),tone(a.status))}<p class="detail-copy">${E(a.reason)}</p><div class="detail-copy">${facts([['Causation',a.cause],['Reviewer',a.actor],['Open review owner',a.owner],['Next review',date(a.due)],['Finance',a.finance]])}</div>`:'<p class="small">No current assessment. Unknown remains visible until a reviewer records an evidence-based decision.</p>')}${card('Separate Commercial goodwill',g?`${pill(g.decision,g.decision==='Approved'?'success':'warning')}<p class="detail-copy">${E(g.reason)}</p><p class="small detail-copy">${E(g.authority)} · ${E(g.actor)} · exact plan ${E(g.planId)}</p>`:'<p class="small">Commercial can approve or decline goodwill for an exact proposed resolution plan. It does not change warranty entitlement or create a credit.</p>',actionButton('goodwill','Record goodwill decision'))}${card('Assessment history',recordHistory(c.assessments,x=>`${pill(pretty(x.status),tone(x.status))}<p>${E(x.reason)}</p><p class="tiny">Terms r${x.sourceRevision} · evidence r${x.evidenceRevision} · ${E(x.actor)} · ${date(x.at)}${x.id===a?.id?' · current':' · retained original'}</p>`))}</div><aside class="stack">${card('Independent dates',facts([['Purchase',date(c.asset.purchase)],['Installation',date(c.asset.installation)],['Commissioning',date(c.asset.commissioning)],['Warranty start',date(v.warrantyStart)],['Warranty end',date(v.warrantyEnd)],['Failure reported',date(c.reported)],['Agreement start',date(v.agreementStart)],['Agreement expiry',date(v.agreementEnd)]]),'','No date is derived from record creation. Replacement does not automatically restart warranty.')}${card('Maintenance agreement',`<p class="small">${E(v.agreement)}</p><p class="detail-copy">${E(v.maintenanceTerms)}</p>`)}${boundary()}</aside></div>`;}
function renderResolution(c){const p=M.plan(c),auth=M.authorisation(c),req=c.requests.find(x=>x.planId===p?.id),ex=c.execution,m=c.maintenanceReviews.at(-1);return heading('Resolution plan','Define the remedy, review its authority and preserve the original equipment and obligation.',!ex?actionButton('plan',p?'Prepare successor plan':'Prepare resolution plan',true):'')+decisions(c)+`<div class="two-col"><div class="stack">${card('Proposed remedy',p?`${pill(p.kind,'info')}${pill('Plan r'+p.revision)}<p class="detail-copy">${E(p.scope)}</p><div class="detail-copy">${facts([['Owner',p.owner],['Requested target',date(p.target)],['Access / shutdown',p.access],['Rationale',p.reason]])}</div><div class="record-actions">${!ex?actionButton('authorise','Review work authority',true):''}${button('planHistory','Inspect plan history','','quiet')}</div>`:'<p class="small">Prepare investigation, repair, return, replacement or loan scope against the reviewed evidence and coverage decision.</p>')}${p?card('Work authority & receiving request',`${auth?note('Exact local scope authorised. Crew booking, site access confirmation and billing remain separate.','success'):note(M.gates(c).join(' ')||'Ready for the Service owner to review exact work authority.','warning')}${auth?`<p class="small detail-copy">${E(auth.authority)} · ${E(auth.actor)}</p>`:''}${req?`<div class="detail-copy">${facts([['Request',req.id],['State',req.state],['Receiving owner',req.owner],['Booking','Not confirmed by this workspace']])}</div><p class="hash detail-copy">SHA-256 ${E(req.hash)}</p><div class="record-actions">${button('requestDetail','Inspect exact request')}${c.id==='wa-1'&&p.kind==='Replace'&&!ex?actionButton('execution','Review replacement result',true):''}</div>`:`<div class="record-actions">${actionButton('request','Prepare owned work request')}</div>`}`):''}${ex?card('Reviewed replacement result',`${pill(ex.outcome,'success')}<p class="small detail-copy">${E(ex.ref)} · ${date(ex.date)} · embedded later-step evidence</p><div class="detail-copy">${facts([['Original asset',ex.originalAsset.name+' · '+ex.originalAsset.serial],['Original disposition',ex.removedDisposition],['Successor asset',ex.replacement.name+' · '+ex.replacement.serial],['Successor warranty','Not established'],['Predecessor link',ex.replacement.predecessor]])}</div>`,'','This local result does not update Equipment, stock, a booking or a service report in another workspace.') :''}${ex?card('Maintenance impact review',`${facts([['Original obligation',ex.maintenance.occurrence],['Original due',date(ex.maintenance.originalDue)],['Current decision',m?.disposition||ex.maintenance.state],['Owner',m?.owner||ex.maintenance.owner],['Review due',date(m?.due||ex.maintenance.due)]])}<p class="small detail-copy">${E(m?.reason||ex.maintenance.note)}</p><div class="record-actions">${actionButton('maintenance','Record maintenance review')}${button('links','Open related design references','','quiet')}</div>`,'','Future maintenance requires its own reviewed plan. No automatic cancellation, reassignment or warranty reset occurs.') :''}</div><aside class="stack">${card('Selected equipment',facts([['Customer',c.customer],['Site',c.site],['Physical location',c.asset.location],['Served areas',c.asset.serves.join(' · ')],['Serial',c.asset.serial||'Not established']]))}${card('Remaining actions',followups(c),actionButton('followup','Add follow-up'))}${card('Decision timeline',timeline(c))}</aside></div>`;}
function renderCustomer(c){const u=c.updates.at(-1),r=M.customerResponse(c);return heading('Customer outcome','Retain the exact remedy update, evidence of presentation and the customer’s response.',actionButton('communication','Prepare customer update',true))+decisions(c)+`<div class="two-col"><div class="stack">${card('Customer resolution',`${pill(M.customerState(c),M.customerState(c)==='Resolved'?'success':'info')}<p class="detail-copy">${c.execution?E(c.execution.outcome)+' · '+date(c.execution.date):'The remedy has not yet been reviewed as completed.'}</p><div class="record-actions">${actionButton('customerClose','Record customer resolution')}${actionButton('followup','Add customer follow-up')}</div>`,'','Customer resolution does not close supplier recovery, recognise a credit or complete future maintenance.')}${u?card('Exact customer update',`${facts([['Revision','r'+u.revision],['Recipient',u.recipient+' · '+u.customer],['Delivery',u.state]])}<div class="customer-sheet detail-copy">${E(u.body)}</div><p class="hash detail-copy">SHA-256 ${E(u.hash)}</p><div class="record-actions">${button('updateHistory','Inspect update history')}${button('exportUpdate','Export exact update')}${actionButton('response','Record customer response',true)}</div>`):card('Customer update not yet prepared','<p class="small">After reviewing the remedy, prepare customer-safe wording and confirm the intended recipient. Internal cause disputes, supplier correspondence and recovery figures are not automatically copied into the update.</p>')}${card('Current customer response',r?`${pill(r.status,r.status==='Accepted'?'success':'warning')}<p class="detail-copy">${E(r.reason)}</p><div class="detail-copy">${facts([['Respondent',r.respondent],['Presented content',r.updateId],['Presentation evidence',r.presentationRef],['Response date',date(r.date)],['Follow-up owner',r.owner||'No response follow-up required'],['Follow-up due',r.due?date(r.due):'Not applicable']])}</div>`:'<p class="small">No response against the current update. Unavailability is recorded explicitly; it is never treated as acceptance.</p>')}${card('Owned follow-up',followups(c),actionButton('followup','Add follow-up'))}</div><aside class="stack">${card('Customer contact',facts([['Contact',c.contact],['Customer',c.customer],['Site',c.site],['Technical owner',c.owner]]))}${card('Supplier position',`<p>${E(selectedClaimStatus(c))}</p><p class="small detail-copy">${M.claim(c)?money(M.outstanding(M.claim(c)))+' of claimed recovery is still unresolved.':'No supplier claim has been prepared.'}</p><div class="record-actions">${button('goSupplier','Review recovery')}</div>`)}${card('Response history',recordHistory(c.responses,x=>`${pill(x.status)}<p class="small">${E(x.updateId)} · ${date(x.date)}</p><p>${E(x.reason)}</p>`))}</aside></div>`;}
function renderSupplier(c){const k=M.claim(c),r=M.response(k);return heading('Supplier recovery','Coordinate the exact claim, physical return and Finance evidence as separate records.',!k?actionButton('claim','Prepare supplier claim',true):'')+decisions(c)+`<div class="two-col"><div class="stack">${k?`${card('Recovery position',`<div class="stat-row">${[['Claimed',k.requestedCents],['Supplier approved',r?.approvedCents||0],['Credit linked',M.credited(k)],['Unresolved',M.outstanding(k)]].map(([l,n])=>`<div><small>${l}</small><strong>${money(n)}</strong></div>`).join('')}</div><p class="small">AUD excluding tax · illustrative amounts · claimed or approved recovery is not cash received.</p><div class="detail-copy">${facts([['Claim',k.id],['Supplier',k.supplier],['Scope',k.scope],['Owner',k.owner],['Next review',date(k.due)],['Supplier state',selectedClaimStatus(c)]])}</div><div class="record-actions">${button('claimDetail','Inspect exact claim')}${!k.submission?actionButton('submitClaim','Record submission evidence'):actionButton('supplierResponse','Record supplier response',true)}</div>`)}${card('Supplier response',r?`${pill(r.status,r.status==='Rejected'?'danger':'info')}<p class="detail-copy">${E(r.reason)}</p><p class="small detail-copy">${E(r.ref)} · ${date(r.date)} · ${E(r.owner)}</p>`:'<p class="small">No supplier response. Preparing or submitting a claim does not establish approval.</p>')}${card('Physical return',recordHistory(k.returns,x=>`${pill(x.kind)}<p>${E(x.reason)}</p><p class="small">${E(x.ref)} · ${date(x.date)} · ${x.quantity} ${E(x.unit)} · ${E(x.serial)}</p>`),actionButton('returnEvent','Record return evidence'),'SC-08 receives return authorisation, receipt and disposition separately. This preview does not move stock.')}${card('Finance credit evidence',recordHistory(k.credits,x=>`<h3>${money(x.cents)} · ${E(x.ref)}</h3><p class="small">${E(x.company)} · ${date(x.date)} · exact claim ${E(x.claimId)}</p><p>${E(x.reason)}</p>`),actionButton('credit','Link credit evidence'),'Only the Finance preview role can link a fictional ERP credit. The source transaction is not created here.')}${card('Unrecovered disposition',recordHistory(k.dispositions,x=>`<h3>${money(x.cents)} · ${E(x.decision)}</h3><p>${E(x.reason)}</p><p class="small">${E(x.ref)} · ${E(x.actor)}</p>`),actionButton('disposition','Review unrecovered closure'))}${card('Supplier response history',recordHistory(k.responses,x=>`${pill(x.status)}<p>${E(x.reason)}</p><p class="small">${E(x.ref)} · ${date(x.date)} · approved ${money(x.approvedCents)}</p>`))}`:card('No supplier claim prepared','<p class="small">Review evidence and coverage, then switch to the Supplier recovery preview role to prepare an exact claim package. Customer work authority and goodwill remain separate.</p>')}${boundary()}</div><aside class="stack">${card('Recovery worklist',`<div class="linked-worklist">${permitted().filter(x=>M.claim(x)).map(x=>button('openRecovery',`${E(x.title)}<small>${E(selectedClaimStatus(x))} · ${money(M.outstanding(M.claim(x)))} unresolved</small>`,`data-case="${x.id}"`)).join('')||'<p class="small">No claims in the permitted preview.</p>'}</div>`)}${card('Customer position',facts([['Customer outcome',M.customerState(c)],['Remedy',c.execution?.outcome||'Not completed'],['Goodwill',M.goodwill(c)?.decision||'Not decided']]))}${card('Receiving responsibilities','<ul class="plain-list"><li>Service owns technical evidence and the customer remedy.</li><li>Supply Chain owns physical return and supplier coordination.</li><li>Finance matches authoritative credit evidence.</li><li>Customer closure does not settle recovery.</li></ul>',button('links','Linked workspaces','','quiet'))}</aside></div>`;}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function status(s,error=false){$('#save-status').textContent=s;$('#save-status').style.color=error?'#993b2a':'';}
try{lastSaved=localStorage.getItem(KEY);if(lastSaved){const x=JSON.parse(lastSaved);if(!M.validState(x.state)||(x.pending&&(!M.roles[x.pending.role]||!x.pending.cmd||!x.state.receipts[x.pending.cmd.op])))throw new Error('Unsupported saved state');state=x.state;pending=x.pending||null;}}catch{storageError='Saved preview could not be opened. Original bytes are retained for export or explicit reset.';}
function readLocation(){const p=new URLSearchParams(location.hash.slice(1));view=views.some(x=>x[0]===p.get('view'))?p.get('view'):'register';selected=state.cases.some(c=>c.id===p.get('case'))?p.get('case'):'wa-1';query=(p.get('q')||'').slice(0,200);filter=['all','review','customer','recovery','identity'].includes(p.get('filter'))?p.get('filter'):'all';sort=['due','name','case'].includes(p.get('sort'))?p.get('sort'):'due';ownerFilter=M.owners.includes(p.get('owner'))?p.get('owner'):'all';}
function locationUpdate(replace=false){const p=new URLSearchParams({view,case:selected,filter,sort,owner:ownerFilter});if(query)p.set('q',query);history[replace?'replaceState':'pushState'](null,'','#'+p);}
readLocation();window.addEventListener('popstate',()=>{readLocation();render();});
function render(){
 $('#role-label').textContent=`${M.roles[role].name} · ${M.roles[role].description}`;status(pending?'Save outcome needs recovery':storageError?'Local storage needs attention':lastSaved?'Saved in this browser':'Ready · changes save in this browser',!!pending||!!storageError);
 $('#tabs').innerHTML=views.map(([id,label])=>`<button type="button" data-view="${id}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('');
 $('#recovery').innerHTML=pending?note(`<div class="row between"><span>The last save may already be recorded. Recover the original operation before another change.</span>${button('recover','Recover original save')}</div>`,'warning'):storageError?note(E(storageError),'danger'):'';
 if(!now()&&permitted().length)selected=permitted()[0].id;
 const c=now(),hiddenContext=view==='register'||!c||['loading','failed','empty'].includes(readState);$('#context').hidden=hiddenContext;$('#context').innerHTML=hiddenContext?'':`<div><span class="tiny">${E(c.ref)} · ${E(M.phase(c))}</span><h2>${E(c.title)}</h2><p>${E(c.customer)} · ${E(c.site)} · ${E(c.asset.name)}</p></div><div class="context-right"><div class="row">${pill(pretty(M.assessment(c)?.status||'Unknown'),tone(M.assessment(c)?.status||'Unknown'))}${pill('Customer '+M.customerState(c),M.customerState(c)==='Resolved'?'success':'')}</div><p>${E(c.owner)} · next review ${date(c.due)}</p>${button('links','Linked workspaces','','link-button')}</div>`;
 let html;if(!permitted().length)html=empty('No permitted warranty cases','This preview has no record access. Use Preview options to restore the permitted demonstration.');
 else if(readState==='loading')html=empty('Loading warranty cases','No complete or empty result is implied while sources are being retrieved.',button('retry','Show current records'));
 else if(readState==='failed')html=empty('Warranty source could not be read','The saved preview is retained. Retry the fictional read before continuing.',button('retry','Retry read'));
 else if(readState==='empty')html=empty('No warranty cases in this preview','This illustrates an empty permitted register.',button('retry','Restore fictional cases'));
 else{html=({register:()=>renderRegister(),evidence:()=>renderEvidence(c),coverage:()=>renderCoverage(c),resolution:()=>renderResolution(c),customer:()=>renderCustomer(c),supplier:()=>renderSupplier(c)})[view]();if(readState==='partial')html=note('Partial source · two fictional cases are visible. Counts apply to those records only.','warning')+html;}
 $('#content').innerHTML=html;$$('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
}
function show(title,body,action=null,label='Save',wide=false){if($('#modal').open){modalDirty=false;$('#modal').close();}opener=document.activeElement;focusKey=opener?.dataset?.action?{...opener.dataset}:null;modalAction=action;modalVersion=state.version;modalDirty=false;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-submit').hidden=!action;$('#modal-submit').textContent=label;$('#modal-error').hidden=true;$('#cancel-button').textContent=action?'Cancel':'Close';$('#modal').classList.toggle('wide',wide);$('#modal').showModal();}
function closeModal(force=false){if(modalDirty&&!force&&!confirm('Discard your unsaved form changes?'))return;modalDirty=false;$('#modal').close();opener?.focus();}
function persist(next,nextPending=null){if(storageError)throw new Error('Export the retained original data and explicitly reset before saving.');if(fault==='save'){fault='none';throw new Error('The preview save failed before storage. Your form and original records are retained.');}if(localStorage.getItem(KEY)!==lastSaved)throw new Error('Another tab changed the preview. Reload the latest records before saving; your form is retained.');const bytes=JSON.stringify({state:next,pending:nextPending});localStorage.setItem(KEY,bytes);lastSaved=bytes;}
function download(bytes,name,type='application/json'){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function save(cmd,savedRole=role,recovery=false){if(pending&&!recovery)throw new Error('Recover the original save before another action.');if(recovery&&savedRole!==role)throw new Error('Return to the original preview role before recovering its result.');status('Saving…');const result=await M.command(state,cmd,role),uncertain=!recovery&&fault==='unknown';if(uncertain)fault='none';const nextPending=uncertain?{cmd,role}:null;persist(result.state,nextPending);state=result.state;pending=nextPending;modalDirty=false;if($('#modal').open)closeModal(true);render();const target=focusKey?$$('[data-action]').find(n=>Object.entries(focusKey).every(([k,v])=>n.dataset[k]===v)):null;(target||$('#content')).focus();toast(uncertain?'Confirmation was lost. Recover the same saved operation.':result.message);}
const illustration=()=>`<svg class="illustration" viewBox="0 0 720 300" role="img" aria-label="Synthetic illustration of pump housing, seal location and serial plate. Not a field photograph."><rect x="0" y="0" width="720" height="300" fill="#f5f7f9"/><path d="M65 174H210M500 174H660" stroke="#aab4c0" stroke-width="28"/><rect x="195" y="120" width="320" height="115" rx="32" fill="#dce2e9" stroke="#596779" stroke-width="3"/><circle cx="320" cy="176" r="70" fill="#edf0f5" stroke="#596779" stroke-width="3"/><circle cx="320" cy="176" r="39" fill="#f6f7f9" stroke="#993b2a" stroke-width="5"/><rect x="431" y="149" width="61" height="25" fill="white" stroke="#596779"/><path d="M333 139L395 59H550M467 151L591 109" fill="none" stroke="#80530e" stroke-width="2"/><g font-family="PPOBoardRoboto, sans-serif" font-size="15" fill="#242a37"><text x="30" y="33">Illustration only · fictional evidence location</text><text x="414" y="49">Reported seal moisture</text><text x="580" y="102">Serial plate</text><text x="30" y="280">Not a photograph, diagnosis or maintenance instruction.</text></g></svg>`;
function exactPackage(title,records){show(title,records.map(r=>`<article class="decision-history"><h3>${E(r.id)}</h3><pre class="mono-block">${E(r.bytes||JSON.stringify(r,null,2))}</pre>${r.hash?`<p class="hash">SHA-256 ${E(r.hash)}</p>`:''}</article>`).join('')||'<p>No retained package.</p>',null,'',true);}
async function act(type,el){
 if(type==='guide'){show('Follow the Willowbank warranty case',`<p>This fictional scenario keeps a customer remedy moving while responsibility and recovery remain independently reviewed.</p><ol class="step-list"><li><b>Failure & evidence:</b> open Willowbank, load the missing demonstration evidence, then review the current set.</li><li><b>Coverage assessment:</b> record <b>Disputed</b> with causation <b>Unconfirmed</b>. The date evidence alone does not settle coverage.</li><li><b>Resolution plan:</b> prepare the default replacement plan. In Preview options, choose the Commercial owner and record <b>Approved</b> goodwill against that plan.</li><li>Return to the Service owner. Review work authority, prepare the owned request, then review the embedded replacement result. Retain an owner for future maintenance review.</li><li><b>Supplier recovery:</b> choose the Supplier recovery owner. Prepare the claim, record fictional submission evidence and a <b>Reviewing</b> response with zero approved amount.</li><li><b>Customer outcome:</b> return to Service owner, prepare the customer-safe update, record evidence of presentation and an <b>Accepted</b> response, then record customer resolution. The supplier claim stays open.</li><li>Optional: explore reservations with owned follow-up, separate return events, supplier partial approval and Finance-only credit matching or unrecovered disposition.</li></ol>${note('These are local design records and clearly labelled later-step evidence. No customer message, supplier claim, booking or financial transaction is sent.','neutral')}`,null,'',true);return;}
 if(type==='settings'){show('Preview options',`${note('Roles illustrate intended responsibility. This local HTML does not authenticate users or enforce server permissions.','neutral')}${select('role','Preview role',Object.entries(M.roles).map(([k,v])=>[k,v.name+' · '+v.description]),role)}${select('read','Read state',[['live','Current records'],['partial','Partial source'],['loading','Loading'],['failed','Read failed'],['empty','Empty'],['denied','Access denied']],readState)}${select('fault','Next save',[['none','Normal'],['save','Fail before saving'],['unknown','Save, then lose confirmation']],fault)}<div class="section-title">Local records</div><div class="row">${button('backup','Export local backup')}${button('reset','Reset demonstration','','danger-button')}</div>`,{local:'settings'},'Apply options');return;}
 if(type==='backup'){download(lastSaved||JSON.stringify({state,pending}),'PPO-Warranty-r01-local-backup.json');return;}
 if(type==='reset'){if(!confirm('Reset this warranty demonstration? Export a backup first if you need to retain your work.'))return;localStorage.removeItem(KEY);state=M.seed();lastSaved=null;pending=null;storageError='';fault='none';role='service';readState='live';selected='wa-1';view='register';query='';filter='all';ownerFilter='all';sort='due';closeModal(true);locationUpdate(true);render();toast('Warranty demonstration reset.');return;}
 if(type==='recover'){if(pending)await save(pending.cmd,pending.role,true);return;}
 if(type==='clear'){query='';filter='all';ownerFilter='all';locationUpdate(true);render();return;}
 if(type==='retry'){readState='live';render();return;}
 if(type==='open'||type==='openRecovery'){if(!permitted().some(c=>c.id===el.dataset.case))throw new Error('The selected case is not permitted.');selected=el.dataset.case;view=type==='open'?'evidence':'supplier';locationUpdate();render();$('#content').focus();return;}
 if(type==='goSupplier'){view='supplier';locationUpdate();render();$('#content').focus();return;}
 const c=now();if(!c)throw new Error('No permitted warranty case is selected.');const p=M.plan(c),k=M.claim(c),u=c.updates.at(-1);
 if(type==='links'){const base='https://github.com/deanrfiedler-gif/powerplants-one/blob/d041de7c40e7ba73acdef3252d5f18f1bf8ccb2f/';const links=[['Maintenance','docs/reference/ui/maintenance/PPO-Service-Agreements-and-Maintenance-Workspace-r01.html'],['Work Orders','docs/reference/ui/service/PPO-Work-Orders-Workspace-r01.html'],['Service Review & Reports','docs/reference/ui/service-review/PPO-Service-Review-and-Reports-Workspace-r02.html'],['Equipment & Installed Base','docs/reference/ui/equipment/PPO-Equipment-and-Installed-Base-Workspace-r02.html'],['Finance','docs/reference/ui/finance/PPO-Finance-and-Commercial-Controls-r02.html'],['Supply Chain receiving contract','docs/contracts/supply-chain-readiness.md']];show('Linked workspaces and receiving context',`${facts([['Warranty case',c.ref],['Customer',c.customer],['Site identity',c.siteId],['Original equipment',c.asset.id],['Exact request',c.requests.at(-1)?.id||'Not prepared'],['Supplier claim',k?.id||'Not prepared']])}<div class="section-title">Existing design references</div><ul class="plain-list">${links.map(([l,path])=>`<li><a href="${base+path}" target="_blank" rel="noopener">${l} · open GitHub reference</a></li>`).join('')}</ul><div class="detail-copy">${note('SC-08 is a future receiving workflow. These links open existing design/contract references; they do not open or create corresponding live records. This standalone preview does not exchange state with other HTML files.','neutral')}</div><div class="record-actions">${button('exportHandover','Export receiving context')}</div>`,null,'',true);return;}
 if(type==='exportHandover'){download(JSON.stringify({schema:'PPO-WARRANTY-RECEIVING-PREVIEW-r01',caseRef:c.ref,siteId:c.siteId,originalAsset:c.asset,assessment:M.assessment(c)||null,requests:c.requests,reviewedResult:c.execution,maintenanceReviews:c.maintenanceReviews,claim:k,followups:c.followups,limitation:'Synthetic design export; no receiving API or import contract is implemented.'},null,2),'PPO-Warranty-r01-receiving-context.json');return;}
 if(type==='evidenceDetail'){const e=c.evidence.find(x=>x.id===el.dataset.id);if(!e)return;show(e.title,`${facts([['Reference',e.ref],['Kind',e.kind],['Source date',date(e.date)],['Availability',e.available?'Available':'Original unavailable'],['Visibility',e.visibility]])}<p class="detail-copy">${E(e.content)}</p>${e.illustration?`<div class="detail-copy">${illustration()}</div>`:''}${e.supersedes?`<p class="small detail-copy">Supersedes unavailable reference ${E(e.supersedes)}; the original stays in history.</p>`:''}`,null,'',true);return;}
 if(type==='terms'){show('Retained warranty source versions',recordHistory(c.sources,v=>`<h3>${E(v.ref)} · context r${v.revision}</h3><p>${E(v.terms)}</p><div class="detail-copy">${facts([['Source',v.available?'Available':'Unavailable'],['Warranty start',date(v.warrantyStart)],['Warranty end',date(v.warrantyEnd)],['Date basis',v.startBasis]])}</div>`),null,'',true);return;}
 if(type==='planHistory'){exactPackage('Retained plan and work authority',c.plans.map(x=>({...x,bytes:JSON.stringify({plan:x,authorisation:c.authorisations.find(a=>a.planId===x.id)||null,goodwill:c.goodwill.filter(g=>g.planId===x.id)},null,2)})));return;}
 if(type==='requestDetail'){exactPackage('Exact retained work requests',c.requests);return;}
 if(type==='claimDetail'){exactPackage('Exact supplier claim package',c.claims);return;}
 if(type==='updateHistory'){exactPackage('Exact customer update revisions',c.updates);return;}
 if(type==='exportUpdate'){if(u)download(u.bytes,`PPO-Warranty-customer-update-r${String(u.revision).padStart(2,'0')}.json`);return;}
 if(!enabled(type))throw new Error('This preview role cannot perform this action.');
 const confirm=()=>check('confirm','I reviewed the exact record, source evidence and separate responsibilities.');
 const decisionDue=()=>select('owner','Review owner',ownerOptions,'Alex Morgan')+field('due','Review due','2026-09-22','date');
 const supplierDue=()=>select('owner','Recovery owner',ownerOptions,'Sam Patel')+field('due','Recovery review due','2026-09-23','date');
 if(type==='loadEvidence'){show('Review recovered demonstration evidence',`${note('Fictional handover successor r02 records warranty start 26 September 2024 and end 25 September 2026 for the same pump serial. Installation and commissioning dates stay unchanged.','info')}<p class="detail-copy">The earlier missing-source reference remains in history. Loading this evidence invalidates the previous review and current coverage decision.</p>${confirm()}`,{type},'Retain recovered evidence');return;}
 if(type==='addEvidence'){show('Add an internal evidence reference',`${note('Record source metadata and observed facts. This form does not upload a file or verify an external document.','neutral')}${select('kind','Evidence type',['Finding','Image reference','Technical report','Purchase record','Correspondence'].map(x=>[x,x]))}${field('title','Evidence title')}${field('ref','Exact source reference')}${field('date','Source date',M.TODAY,'date')}${area('content','Observed facts and source availability')}${confirm()}`,{type},'Add reference');return;}
 if(type==='reviewEvidence'){show('Review the current evidence set',`${facts([['Evidence set','r'+c.evidenceRevision],['Source context','r'+M.source(c).revision],['Available references',String(c.evidence.filter(e=>e.available).length)]])}${area('reason','Evidence review basis','Reviewed the available source records, serial context and missing facts. Observations do not establish the cause of failure.')}${confirm()}`,{type},'Record evidence review');return;}
 if(type==='assess'){show('Record coverage and causation',`${select('status','Warranty coverage',['Unknown','Disputed','Covered','NotCovered','NotApplicable'].map(x=>[x,pretty(x)]),'Disputed')}${select('cause','Cause assessment',['Unconfirmed','Manufacturing defect','Installation damage','Wear','No fault found'].map(x=>[x,x]),'Unconfirmed')}${area('reason','Assessment and source basis','Failure falls within the sourced fictional period, but the supplier and customer disagree on cause. Keep entitlement disputed pending technical evidence.')}${decisionDue()}${confirm()}`,{type},'Record assessment');return;}
 if(type==='plan'){show('Prepare a resolution plan',`${select('kind','Remedy type',['Investigate','Repair','Return','Replace','Loan'].map(x=>[x,x]),'Replace')}${area('scope','Exact work scope',M.REPLACEMENT_SCOPE)}${select('owner','Resolution owner',ownerOptions,'Alex Morgan')}${field('target','Requested work date','2026-09-19','date')}${area('access','Access and shutdown review','Confirm the crop window, isolate the shared pump and review affected Greenhouse 01, Tunnel 01 and Propagation House 01 before attendance.')}${area('reason','Resolution rationale','Prepare a replacement to restore the customer service while responsibility and supplier recovery remain under review.')}${confirm()}`,{type},'Retain proposed plan');return;}
 if(type==='goodwill'){show('Record Commercial goodwill',`${facts([['Exact plan',p?p.id:'Prepare a current plan first'],['Warranty',pretty(M.assessment(c)?.status||'Unknown')]])}${select('decision','Goodwill decision',[['Approved','Approved'],['Declined','Declined']],'Approved')}${field('authority','Commercial authority reference','SYN-WAR-GOODWILL-01')}${area('reason','Commercial decision basis','Approve the exact proposed replacement as customer goodwill. This does not concede warranty entitlement or approve Finance posting.')}${confirm()}`,{type},'Record goodwill');return;}
 if(type==='authorise'){show('Review exact work authority',`${note(M.gates(c).join(' ')||'The current plan has the required evidence and responsibility decisions. Booking and billing remain separate.',M.gates(c).length?'warning':'success')}${field('authority','Work authority reference','SYN-WAR-WORK-AUTH-01')}${area('reason','Work authorisation basis','Authorise the exact proposed scope under the recorded Commercial goodwill decision, subject to separate site and scheduling controls.')}${confirm()}`,{type},'Record authorisation');return;}
 if(type==='request'){show('Prepare owned work request',`${facts([['Exact plan',p?.id||'Not prepared'],['Work authority',M.authorisation(c)?.id||'Not authorised'],['Booking','Separate receiving decision']])}${select('owner','Receiving owner',ownerOptions,'Robin Ellis')}${area('note','Receiving context','Review the authorised replacement, access and isolation conditions, available materials and commissioning evidence before confirming a crew booking.')}${confirm()}`,{type},'Prepare request');return;}
 if(type==='execution'){show('Review the replacement result',`${note('Embedded later-step evidence for the default Willowbank replacement request on 19 September. It illustrates a reviewed Service report; it does not run Work Orders or scheduling.','info')}${facts([['Result','SYN-WAR-SERVICE-RESULT-01 r01'],['Removed serial',c.asset.serial],['Replacement serial','SYN-PUMP-26-REPL-001'],['Result','Replacement installed and commissioned; original quarantined at site'],['Warranty','Successor dates not established']])}${select('owner','Maintenance review owner',ownerOptions,'Alex Morgan')}${field('due','Maintenance review due','2026-09-22','date')}${confirm()}`,{type},'Retain reviewed result');return;}
 if(type==='maintenance'){show('Review future maintenance effects',`${select('disposition','Maintenance disposition',['Hold future generation','Prepare successor plan review','No transfer — further evidence required'].map(x=>[x,x]),'Prepare successor plan review')}${decisionDue()}${area('reason','Maintenance impact review','Retain the original 15 September obligation and its equipment context. Review successor tasks and sources before any future plan change.')}${confirm()}`,{type},'Record owned review');return;}
 if(type==='communication'){show('Prepare an exact customer update',`${facts([['Intended recipient',c.contact+' · '+c.customer],['Delivery','Prepared locally; no message will be sent']])}${area('body','Customer-safe content','The irrigation pump replacement was completed and commissioned on 19 September. The original pump has been retained for investigation. Alex Morgan will review future maintenance requirements by 22 September. Please confirm the recorded remedy and advise any remaining concerns.')}${check('confirm','I reviewed the recipient and wording. Internal correspondence and recovery figures are excluded.')}`,{type},'Retain customer update');return;}
 if(type==='response'){show('Record response to exact content',`${facts([['Update',u?.id||'Prepare a customer update first'],['Recipient',c.contact]])}${select('status','Customer response',['Accepted','Reservations','Disagreed','Unavailable'].map(x=>[x,x]),'Accepted')}${field('presentationRef','Presentation evidence reference','SYN-WAR-CUSTOMER-PRESENTATION-01')}${field('date','Response date','2026-09-20','date')}${area('reason','Customer response evidence','Casey confirmed the replacement remedy and the recorded next maintenance review. This does not address supplier recovery.')}${select('owner','Reservation follow-up owner',ownerOptions,'Alex Morgan')}${field('due','Reservation follow-up due','2026-09-22','date')}${confirm()}`,{type,fixed:{updateId:u?.id}},'Retain response');return;}
 if(type==='customerClose'){show('Record customer resolution',`${note('Requires the reviewed remedy, acceptance of the exact current update and completed customer follow-up. Supplier and maintenance records remain open independently.','neutral')}${area('reason','Customer resolution basis','The reviewed remedy and exact customer update are accepted. Supplier recovery and owned maintenance review remain separately visible.')}${confirm()}`,{type},'Record customer resolution');return;}
 if(type==='claim'){show('Prepare the supplier claim package',`${field('supplier','Supplier','Demonstration Pump Supplier')}${area('scope','Exact claim scope','One replacement pump assembly; fictional parts recovery only. Labour, freight and customer goodwill are not assumed recoverable.')}${field('amount','Claimed AUD excluding tax','1250.00')}${supplierDue()}${confirm()}`,{type},'Retain claim package');return;}
 if(type==='submitClaim'){show('Record external submission evidence',`${note('This records fictional evidence of submission outside the workspace. It does not send a supplier claim.','neutral')}${field('ref','External submission reference','SYN-WAR-CLAIM-ACK-01')}${field('date','Submission date','2026-09-19','date')}${confirm()}`,{type},'Record submission evidence');return;}
 if(type==='supplierResponse'){show('Record supplier response',`${select('status','Supplier response',['Reviewing','More information','Approved','Partially approved','Rejected'].map(x=>[x,x]),'Reviewing')}${field('amount','Approved AUD excluding tax','0.00')}${field('ref','Supplier evidence reference','SYN-WAR-SUPPLIER-RESPONSE-01')}${field('date','Supplier response date','2026-09-20','date')}${area('reason','Supplier response basis','Supplier acknowledges the claim and is reviewing the technical evidence. Approval and recovery remain outstanding.')}${supplierDue()}${confirm()}`,{type},'Retain supplier response');return;}
 if(type==='returnEvent'){show('Record separate return evidence',`${select('kind','Return event',['Authorised','Received','Disposed','Not required'].map(x=>[x,x]),'Authorised')}${field('ref','Return evidence reference','SYN-WAR-RMA-01')}${field('date','Return event date','2026-09-20','date')}${area('reason','Return condition and disposition','One original pump, serial retained. Keep physical custody, supplier responsibility and financial settlement separate.')}${confirm()}`,{type},'Record return evidence');return;}
 if(type==='credit'){show('Link authoritative credit evidence',`${note('Finance-only fictional evidence link. No MYOB transaction, customer credit or cash receipt is created.','neutral')}${field('company','ERP company','SYN-PPO-AU')}${field('ref','ERP credit reference','SYN-ERP-SUPPLIER-CREDIT-001')}${field('amount','Credit AUD excluding tax','750.00')}${field('date','Credit source date','2026-09-23','date')}${area('reason','Finance matching evidence','Matched the exact fictional supplier claim, company, currency, tax basis and approved amount to the retained ERP credit evidence.')}${confirm()}`,{type},'Link credit evidence');return;}
 if(type==='disposition'){show('Review unrecovered claim closure',`${facts([['Unresolved amount',money(M.outstanding(k))],['Treatment','Unrecovered; not a supplier credit']])}${field('ref','Finance disposition evidence','SYN-WAR-RECOVERY-DISPOSITION-01')}${area('reason','Unrecovered closure basis','Reviewed the final supplier decision and remaining amount. Retain this balance as unrecovered in the design record; no financial posting is made.')}${confirm()}`,{type},'Record unrecovered disposition');return;}
 if(type==='followup'){show('Assign a separate follow-up',`${select('kind','Follow-up type',['Customer','Technical','Supplier','Finance'].map(x=>[x,x]),view==='supplier'?'Supplier':view==='customer'?'Customer':'Technical')}${area('title','Next action')}${select('owner','Follow-up owner',ownerOptions,c.owner)}${field('due','Follow-up due','2026-09-22','date')}`,{type},'Assign follow-up');return;}
 if(type==='completeFollowup'){const f=c.followups.find(x=>x.id===el.dataset.id);if(!f)return;show('Record follow-up outcome',`${facts([['Action',f.title],['Owner',f.owner]])}${area('reason','Completion outcome')}`,{type,fixed:{followupId:f.id}},'Complete follow-up');return;}
 if(type==='assign'){show('Assign the next case review',`${select('owner','Case review owner',ownerOptions,c.owner)}${field('due','Next review due',c.due,'date')}${area('reason','Ownership reason')}`,{type},'Save next review');}
}
$('#modal-form').addEventListener('input',()=>modalDirty=true);$('#modal-form').addEventListener('change',()=>modalDirty=true);
$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();if(!modalAction)return;const data=Object.fromEntries(new FormData(e.target));if(modalAction.local==='settings'){role=data.role;readState=data.read;fault=data.fault;closeModal(true);render();return;}const cmd={op:crypto.randomUUID(),type:modalAction.type,caseId:selected,expectedVersion:modalVersion,payload:{...modalAction.fixed,...data,confirm:data.confirm==='on'}};$('#modal-submit').disabled=true;try{await save(cmd);}catch(error){$('#modal-error').textContent=error.message;$('#modal-error').hidden=false;status('Not saved · form retained',true);$('#modal-error').scrollIntoView({block:'nearest'});}finally{$('#modal-submit').disabled=false;}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('click',async e=>{if(e.target.closest('[data-close]')){closeModal();return;}const n=e.target.closest('[data-view]');if(n){view=n.dataset.view;locationUpdate();render();$('#content').focus();return;}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;locationUpdate(true);render();return;}const a=e.target.closest('[data-action]');if(a)try{await act(a.dataset.action,a);}catch(error){if($('#modal').open){$('#modal-error').textContent=error.message;$('#modal-error').hidden=false;}else toast(error.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const caret=e.target.selectionStart;locationUpdate(true);render();$('#search')?.focus();$('#search')?.setSelectionRange(caret,caret);},160);}});
document.addEventListener('change',e=>{if(e.target.id==='register-filter')filter=e.target.value;else if(e.target.id==='owner-filter')ownerFilter=e.target.value;else if(e.target.id==='register-sort')sort=e.target.value;else return;locationUpdate(true);render();});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-view]'))return;const tabs=$$('[data-view]'),i=tabs.indexOf(e.target);let j;if(e.key==='ArrowRight')j=(i+1)%tabs.length;else if(e.key==='ArrowLeft')j=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=tabs.length-1;if(j!==undefined){e.preventDefault();tabs[j].focus();tabs[j].scrollIntoView({inline:'nearest',block:'nearest'});}});
window.addEventListener('storage',e=>{if(e.key===KEY){status('Another tab changed the preview · reload before saving',true);toast('The saved preview changed in another tab. Your form is retained.');}});
window.WA_DEMO={state:()=>M.clone(state),ui:()=>({selected,view,role,readState,query,filter,ownerFilter,pending:!!pending}),key:KEY};render();
})();
